    "eStarter": "// [TEACHING SIMULATION — Component Tree Hierarchy Builder]\nclass ComponentTreeBuilder {\n  constructor() {\n    this.components = new Map();\n  }\n  registerComponent(name, renderFn, allowedChildren = []) {\n    this.components.set(name, { name, renderFn, allowedChildren });\n  }\n  buildNode(name, props = {}, children = []) {\n    const comp = this.components.get(name);\n    if (!comp) throw new Error(`Component ${name} is not registered`);\n    // Verify children types if allowedChildren is non-empty\n    if (comp.allowedChildren.length > 0) {\n      for (const child of children) {\n        if (!comp.allowedChildren.includes(child.name)) {\n          throw new Error(`Child ${child.name} is not allowed inside ${name}`);\n        }\n      }\n    }\n    return {\n      name,\n      props,\n      children,\n      render: () => comp.renderFn(props, children.map(c => c.render()))\n    };\n  }\n}",
