    "eDesc": "Implement class ReactComponentRenderer managing component functions, createElement calls, and recursive virtual element resolution.",
    "eStarter": "// [TEACHING SIMULATION — React Element Virtual Tree Renderer]\nclass ReactComponentRenderer {\n  createElement(type, props = null, ...children) {\n    const normalizedProps = { ...(props || {}) };\n    if (children.length === 1) {\n      normalizedProps.children = children[0];\n    } else if (children.length > 1) {\n      normalizedProps.children = children;\n    }\n    return { type, props: normalizedProps };\n  }\n  renderToVirtualTree(element) {\n    if (typeof element !== 'object' || element === null) return element;\n    if (typeof element.type === 'function') {\n      // Execute component function with props\n      const childElement = element.type(element.props);\n      return this.renderToVirtualTree(childElement);\n    }\n    // Native element: resolve children\n    const resolvedProps = { ...element.props };\n    if (Array.isArray(resolvedProps.children)) {\n      resolvedProps.children = resolvedProps.children.map(c => this.renderToVirtualTree(c));\n    } else if (resolvedProps.children && typeof resolvedProps.children === 'object') {\n      resolvedProps.children = this.renderToVirtualTree(resolvedProps.children);\n    }\n    return { type: element.type, props: resolvedProps };\n  }\n}",
    "eHint": "If element.type is function invoke it and recursively render; otherwise resolve children recursively.",
