    "eTitle": "Effect Lifecycle & Cleanup Scheduler Engine",
    "eDesc": "Implement class EffectLifecycleScheduler managing dependency diffing with Object.is, executing cleanup functions before re-runs, and unmounting cleanly.",
    "eStarter": "// [TEACHING SIMULATION — Effect Lifecycle & Cleanup Scheduler]\nclass EffectLifecycleScheduler {\n  constructor() {\n    this.activeCleanup = null;\n    this.prevDeps = null;\n    this.executionLog = [];\n  }\n  scheduleEffect(effectFn, nextDeps) {\n    let shouldRun = false;\n    if (this.prevDeps === null || !nextDeps) {\n      shouldRun = true; // Initial run or omitted deps\n    } else {\n      // Compare each dependency using Object.is:\n      shouldRun = nextDeps.some((dep, i) => !Object.is(dep, this.prevDeps[i]));\n    }\n    if (shouldRun) {\n      if (this.activeCleanup) {\n        this.executionLog.push('RUN_CLEANUP');\n        this.activeCleanup();\n      }\n      this.executionLog.push('RUN_SETUP');\n      this.activeCleanup = effectFn() || null;\n      this.prevDeps = nextDeps ? [...nextDeps] : null;\n    }\n  }\n  unmount() {\n    if (this.activeCleanup) {\n      this.executionLog.push('UNMOUNT_CLEANUP');\n      this.activeCleanup();\n      this.activeCleanup = null;\n    }\n  }\n}",
    "eHint": "In scheduleEffect compare dependencies using Object.is, call previous activeCleanup if running, store return value in activeCleanup.",
    "eTest": "const scheduler = new EffectLifecycleScheduler();\nlet cleanupCalled = 0;\nlet setupCalled = 0;\n// 1. Initial run\nscheduler.scheduleEffect(() => {\n  setupCalled++;\n  return () => { cleanupCalled++; };\n}, ['room-1']);\nif (setupCalled !== 1 || cleanupCalled !== 0) throw new Error('Initial effect setup failed');\n// 2. Unchanged deps -> effect skipped\nscheduler.scheduleEffect(() => { setupCalled++; }, ['room-1']);\nif (setupCalled !== 1) throw new Error('Effect should skip when deps are unchanged');\n// 3. Changed deps -> cleanup previous then setup new\nscheduler.scheduleEffect(() => {\n  setupCalled++;\n  return () => { cleanupCalled++; };\n}, ['room-2']);\nif (cleanupCalled !== 1 || setupCalled !== 2) throw new Error('Cleanup before re-sync failed');\n// 4. Unmount\nscheduler.unmount();\nif (cleanupCalled !== 2) throw new Error('Unmount cleanup failed');",
