    "eDesc": "Implement class DomAndMutableRefEngine managing DOM node attachment, imperative focus invocation, and persistent timer ID storage across simulated renders.",
    "eStarter": "// [TEACHING SIMULATION — DOM Ref & Mutable Reference Engine]\nclass DomAndMutableRefEngine {\n  constructor() {\n    this.domRefs = new Map(); // name -> { current: mockDomNode }\n    this.mutableRefs = new Map(); // name -> { current: value }\n    this.renderCount = 0;\n  }\n  createRef(name, initialValue = null, isDomRef = false) {\n    const refObj = { current: initialValue };\n    if (isDomRef) this.domRefs.set(name, refObj);\n    else this.mutableRefs.set(name, refObj);\n    return refObj;\n  }\n  attachDomNode(refName, mockElement) {\n    const ref = this.domRefs.get(refName);\n    if (ref) ref.current = mockElement;\n  }\n  focusElement(refName) {\n    const ref = this.domRefs.get(refName);\n    if (ref && ref.current && typeof ref.current.focus === 'function') {\n      ref.current.focus();\n      return true;\n    }\n    return false;\n  }\n  setMutableValue(refName, value) {\n    const ref = this.mutableRefs.get(refName);\n    if (ref) {\n      ref.current = value; // Does NOT increment this.renderCount!\n      return ref.current;\n    }\n  }\n}",
    "eHint": "In createRef instantiate { current: initialValue }; in focusElement invoke current.focus(); in setMutableValue mutate ref.current without re-render.",
    "eTest": "const engine = new DomAndMutableRefEngine();\n// 1. Test DOM ref focus\nconst inputRef = engine.createRef('searchInput', null, true);\nlet isFocused = false;\nengine.attachDomNode('searchInput', { focus: () => { isFocused = true; } });\nengine.focusElement('searchInput');\nif (!isFocused) throw new Error('DOM ref focus failed');\n// 2. Test mutable timer ref without re-render\nconst timerRef = engine.createRef('timerId', null, false);\nengine.setMutableValue('timerId', 12345);\nif (timerRef.current !== 12345 || engine.renderCount !== 0) throw new Error('Mutable ref storage failed or caused re-render');",
