    "eTitle": "Explicit State Transition Reducer Engine",
    "eDesc": "Implement class ExplicitStateTransitionReducerEngine simulating pure state transitions, intent-based action routing, and FSM transition constraints.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Explicit State Transition Reducer Engine]\nclass ExplicitStateTransitionReducerEngine {\n  constructor() {\n    this.state = { status: 'idle', data: null, error: null };\n    this.actionHistory = [];\n  }\n  reducer(currentState, action) {\n    // Implement pure transition logic based on currentState.status:\n    // 'idle':\n    //   - 'FETCH_START': return { status: 'loading', data: null, error: null }\n    //   - other actions -> return currentState (reject invalid transition)\n    // 'loading':\n    //   - 'FETCH_SUCCESS': return { status: 'success', data: action.payload, error: null }\n    //   - 'FETCH_FAILURE': return { status: 'error', data: null, error: action.payload }\n    //   - other actions -> return currentState\n    // 'success' | 'error':\n    //   - 'RESET': return { status: 'idle', data: null, error: null }\n    //   - 'FETCH_START': return { status: 'loading', data: null, error: null }\n    //   - other actions -> return currentState\n    \n  }\n  dispatch(action) {\n    this.actionHistory.push(action.type);\n    this.state = this.reducer(this.state, action);\n    return this.state;\n  }\n}",
    "eHint": "In reducer switch on currentState.status, check action.type, and return new immutable state objects.",
    "eTest": "const engine = new ExplicitStateTransitionReducerEngine();\n// 1. Initial idle state\nif (engine.state.status !== 'idle') throw new Error('Initial state must be idle');\n// 2. Reject invalid jump directly from idle to FETCH_SUCCESS\nengine.dispatch({ type: 'FETCH_SUCCESS', payload: ['bad'] });\nif (engine.state.status !== 'idle') throw new Error('Invalid transition from idle to FETCH_SUCCESS should be rejected');\n// 3. Valid FETCH_START -> loading\nengine.dispatch({ type: 'FETCH_START' });\nif (engine.state.status !== 'loading') throw new Error('FETCH_START failed to transition to loading');\n// 4. Valid FETCH_SUCCESS -> success with data\nengine.dispatch({ type: 'FETCH_SUCCESS', payload: ['Task A', 'Task B'] });\nif (engine.state.status !== 'success' || engine.state.data.length !== 2) throw new Error('FETCH_SUCCESS transition failed');\n// 5. Valid RESET -> idle\nengine.dispatch({ type: 'RESET' });\nif (engine.state.status !== 'idle') throw new Error('RESET transition failed');",
