    "aStarter": "function createAsyncStateReducer(state, action) {\n  // Handle 'FETCH_START' -> { status: 'loading', data: null, error: null }\n  // Handle 'FETCH_SUCCESS' -> { status: 'success', data: action.payload, error: null }\n  // Handle 'FETCH_FAILURE' -> { status: 'error', data: null, error: action.payload }\n  // Default -> return state\n  \n}",
