    "eTitle": "Context Dependency Propagation Engine",
    "eDesc": "Implement class ContextDependencyPropagationEngine simulating Provider hierarchy, consumer lookup, and value identity change detection.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Context Dependency Propagation Engine]\nclass ContextDependencyPropagationEngine {\n  constructor(defaultValue = null) {\n    this.defaultValue = defaultValue;\n    this.providerValue = defaultValue;\n    this.consumers = new Map(); // consumerId -> lastSeenValue\n  }\n  setProviderValue(newValue) {\n    const hasChangedIdentity = !Object.is(this.providerValue, newValue);\n    this.providerValue = newValue;\n    if (hasChangedIdentity) {\n      // Notify all registered consumers with the new value\n      for (const [id, _] of this.consumers) {\n        this.consumers.set(id, this.providerValue);\n      }\n    }\n    return hasChangedIdentity;\n  }\n  registerConsumer(consumerId) {\n    this.consumers.set(consumerId, this.providerValue);\n    return this.providerValue;\n  }\n  readContext(consumerId) {\n    return this.consumers.has(consumerId) ? this.consumers.get(consumerId) : this.defaultValue;\n  }\n}",
    "eHint": "In setProviderValue compare this.providerValue to newValue with Object.is, update providerValue and consumers map.",
    "eTest": "const context = new ContextDependencyPropagationEngine('light');\n// 1. Read default before registration\nif (context.readContext('unregistered') !== 'light') throw new Error('Default context value failed');\n// 2. Register consumer\ncontext.registerConsumer('Navbar');\nif (context.readContext('Navbar') !== 'light') throw new Error('Initial consumer value failed');\n// 3. Update provider value\nconst changed = context.setProviderValue('dark');\nif (!changed || context.readContext('Navbar') !== 'dark') throw new Error('Provider update propagation failed');\n// 4. Same reference update\nconst changedSame = context.setProviderValue('dark');\nif (changedSame) throw new Error('Same value should not trigger identity change');",
