    "aHint": "Return object with value property and getter/setter methods.",
    "aTest": "const store = createContextStore('light');\nif (store.getValue() !== 'light') throw new Error('Getter failed');\nstore.setValue('dark');\nif (store.getValue() !== 'dark') throw new Error('Setter failed');"
