    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Component Topology & State Colocator]\nclass ComponentTopologyStateColocator {\n  constructor() {\n    this.tasks = [];\n  }\n  setTasks(taskList) {\n    this.tasks = [...taskList]; // Single Source of Truth: [{ id, text, done, category }]\n  }\n  findNarrowestStateOwner(consumerPaths) {\n    // consumerPaths: Array of component paths e.g. ['App/Layout/Header/Search', 'App/Layout/Header/UserBadge']\n    // Find the common prefix path (the narrowest shared parent component)\n    if (!consumerPaths || consumerPaths.length === 0) return 'App';\n    if (consumerPaths.length === 1) return consumerPaths[0];\n    const splitPaths = consumerPaths.map(p => p.split('/'));\n    let common = [];\n    for (let i = 0; i < splitPaths[0].length; i++) {\n      const segment = splitPaths[0][i];\n      if (splitPaths.every(p => p[i] === segment)) {\n        common.push(segment);\n      } else {\n        break;\n      }\n    }\n    return common.join('/') || 'App';\n  }\n  getDerivedMetrics(categoryFilter = 'ALL') {\n    // Calculate on the fly: visibleTasks, completedCount, completionPercentage\n    \n  }\n}",
