    "eTest": "const colocator = new ComponentTopologyStateColocator();\n// 1. Test finding narrowest owner\nconst sharedParent = colocator.findNarrowestStateOwner([\n  'App/Layout/Header/Search',\n  'App/Layout/Header/UserBadge'\n]);\nif (sharedParent !== 'App/Layout/Header') throw new Error('Failed to find narrowest parent; expected App/Layout/Header, got: ' + sharedParent);\n// 2. Test single consumer colocation\nconst singleOwner = colocator.findNarrowestStateOwner(['App/Sidebar/QuickFilter']);\nif (singleOwner !== 'App/Sidebar/QuickFilter') throw new Error('Single consumer should colocate state locally');\n// 3. Test derived metrics calculation\ncolocator.setTasks([\n  { id: 1, text: 'T1', done: true, category: 'DEV' },\n  { id: 2, text: 'T2', done: false, category: 'DEV' },\n  { id: 3, text: 'T3', done: true, category: 'DESIGN' }\n]);\nconst metrics = colocator.getDerivedMetrics('DEV');\nif (metrics.visibleTasks.length !== 2 || metrics.completedCount !== 2 || metrics.completionPercentage !== 67) {\n  throw new Error('Derived metrics calculation failed');\n}",
    "aTitle": "Derived Task Metrics Calculator",
    "aDesc": "Implement function calculateDerivedTaskMetrics(tasks, filterCategory) returning `{ visibleCount, completedCount, percent }` calculated dynamically during render.",
