    "eTitle": "Normalized Kanban Architecture & State Machine Engine",
    "eDesc": "Implement class NormalizedKanbanArchitectureEngine managing normalized board state, intent-based action dispatching, and column transfers.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Normalized Kanban Architecture Engine]\nclass NormalizedKanbanArchitectureEngine {\n  constructor() {\n    this.state = {\n      tasksById: {},\n      columnsById: {\n        'todo': { id: 'todo', title: 'To Do', taskIds: [] },\n        'in_progress': { id: 'in_progress', title: 'In Progress', taskIds: [] },\n        'done': { id: 'done', title: 'Done', taskIds: [] }\n      },\n      archivedTaskIds: []\n    };\n    this.actionLog = [];\n  }\n  dispatch(action) {\n    this.actionLog.push(action.type);\n    switch (action.type) {\n      case 'TASK_CREATED': {\n        const { id, title, columnId } = action.payload;\n        const nextTasks = { ...this.state.tasksById, [id]: { id, title } };\n        const col = this.state.columnsById[columnId];\n        const nextColumns = {\n          ...this.state.columnsById,\n          [columnId]: { ...col, taskIds: [...col.taskIds, id] }\n        };\n        this.state = { ...this.state, tasksById: nextTasks, columnsById: nextColumns };\n        break;\n      }\n      case 'TASK_MOVED': {\n        const { taskId, fromColId, toColId } = action.payload;\n        const fromCol = this.state.columnsById[fromColId];\n        const toCol = this.state.columnsById[toColId];\n        if (!fromCol || !toCol) break;\n        const nextColumns = {\n          ...this.state.columnsById,\n          [fromColId]: { ...fromCol, taskIds: fromCol.taskIds.filter(id => id !== taskId) },\n          [toColId]: { ...toCol, taskIds: [...toCol.taskIds, taskId] }\n        };\n        this.state = { ...this.state, columnsById: nextColumns };\n        break;\n      }\n      case 'TASK_ARCHIVED': {\n        const { taskId, fromColId } = action.payload;\n        const fromCol = this.state.columnsById[fromColId];\n        if (!fromCol) break;\n        const nextColumns = {\n          ...this.state.columnsById,\n          [fromColId]: { ...fromCol, taskIds: fromCol.taskIds.filter(id => id !== taskId) }\n        };\n        this.state = {\n          ...this.state,\n          columnsById: nextColumns,\n          archivedTaskIds: [...this.state.archivedTaskIds, taskId]\n        };\n        break;\n      }\n    }\n    return this.state;\n  }\n  getDerivedColumnTasks(columnId) {\n    const col = this.state.columnsById[columnId];\n    if (!col) return [];\n    return col.taskIds.map(id => this.state.tasksById[id]).filter(Boolean);\n  }\n}",
    "eHint": "Implement dispatch cases for TASK_CREATED, TASK_MOVED, and TASK_ARCHIVED using immutable updates, and map taskIds in getDerivedColumnTasks.",
    "eTest": "const board = new NormalizedKanbanArchitectureEngine();\n// 1. Create two tasks in 'todo'\nboard.dispatch({ type: 'TASK_CREATED', payload: { id: 't1', title: 'Design Architecture', columnId: 'todo' } });\nboard.dispatch({ type: 'TASK_CREATED', payload: { id: 't2', title: 'Implement Reducer', columnId: 'todo' } });\nlet todoTasks = board.getDerivedColumnTasks('todo');\nif (todoTasks.length !== 2 || todoTasks[0].title !== 'Design Architecture') throw new Error('Task creation failed');\n// 2. Move task t1 from 'todo' to 'in_progress'\nboard.dispatch({ type: 'TASK_MOVED', payload: { taskId: 't1', fromColId: 'todo', toColId: 'in_progress' } });\ntodoTasks = board.getDerivedColumnTasks('todo');\nlet progressTasks = board.getDerivedColumnTasks('in_progress');\nif (todoTasks.length !== 1 || progressTasks.length !== 1 || progressTasks[0].id !== 't1') throw new Error('Task move failed');\n// 3. Architecture Evolution Requirement: Archive task t2\nboard.dispatch({ type: 'TASK_ARCHIVED', payload: { taskId: 't2', fromColId: 'todo' } });\ntodoTasks = board.getDerivedColumnTasks('todo');\nif (todoTasks.length !== 0 || !board.state.archivedTaskIds.includes('t2')) throw new Error('Task archiving failed');",
    "aTitle": "Entity List Normalizer",
    "aDesc": "Implement function normalizeEntityList(items) returning `{ byId: { [id]: item }, allIds: string[] }` for an array of items with `id` properties.",
