    "aHint": "Reduce items into byId object and map to item.id array.",
    "aTest": "const items = [{ id: 'a', title: 'A' }, { id: 'b', title: 'B' }];\nconst norm = normalizeEntityList(items);\nif (norm.allIds.length !== 2 || norm.byId['a'].title !== 'A' || norm.byId['b'].title !== 'B') throw new Error('Normalization failed');"
