    "eTitle": "Nested Layout Outlet Engine",
    "eDesc": "Implement class NestedLayoutOutletEngine managing hierarchical nested layouts, tracking ancestor state continuity, and rendering active sub-outlets.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Nested Layout Outlet Engine]\nclass NestedLayoutOutletEngine {\n  constructor() {\n    this.layoutState = { sidebarCollapsed: false, scrollOffset: 250 };\n    this.renderLog = [];\n  }\n  renderHierarchy(parentLayoutName, childViewName) {\n    this.renderLog.push({ parent: parentLayoutName, child: childViewName, timestamp: Date.now() });\n    return {\n      layout: parentLayoutName,\n      layoutState: { ...this.layoutState },\n      activeOutlet: childViewName,\n      renderCount: this.renderLog.length\n    };\n  }\n  updateLayoutSidebar(collapsed) {\n    this.layoutState.sidebarCollapsed = Boolean(collapsed);\n  }\n}",
    "eHint": "In renderHierarchy return object containing layout name, preserved layoutState, active child view, and render count.",
    "eTest": "const engine = new NestedLayoutOutletEngine();\nengine.updateLayoutSidebar(true);\n// 1. Render child route /settings/profile\nconst view1 = engine.renderHierarchy('SettingsLayout', 'ProfileTab');\nif (view1.layout !== 'SettingsLayout' || view1.activeOutlet !== 'ProfileTab' || view1.layoutState.sidebarCollapsed !== true) {\n  throw new Error('Initial nested layout render failed');\n}\n// 2. Navigate to /settings/billing — layout state must be preserved\nconst view2 = engine.renderHierarchy('SettingsLayout', 'BillingTab');\nif (view2.layout !== 'SettingsLayout' || view2.activeOutlet !== 'BillingTab' || view2.layoutState.sidebarCollapsed !== true || view2.renderCount !== 2) {\n  throw new Error('Layout state preservation failed across sub-route transition');\n}",
    "aTitle": "Nested Route Tree Resolver",
    "aDesc": "Implement function renderNestedRouteTree(routeTree, activePath) returning { parent: string, child: string } from a nested route mapping.",
    "aStarter": "function renderNestedRouteTree(routeTree, activePath) {\n  const node = routeTree[activePath];\n  if (!node) return { parent: 'RootLayout', child: 'NotFound' };\n  return { parent: node.layout, child: node.child };\n}",
    "aHint": "Lookup activePath in routeTree and return parent layout and child component.",
    "aTest": "const tree = { '/admin/users': { layout: 'AdminLayout', child: 'UserList' } };\nconst res = renderNestedRouteTree(tree, '/admin/users');\nif (res.parent !== 'AdminLayout' || res.child !== 'UserList') throw new Error('Nested tree resolver failed');"
