    "eTitle": "Headless Compound Tabs Engine",
    "eDesc": "Implement class HeadlessCompoundTabsEngine managing compound tab state, context validation guardrails, and state snapshot exposure.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Headless Compound Tabs Engine]\nclass HeadlessCompoundTabsEngine {\n  constructor(defaultIndex = 0) {\n    this.activeIndex = defaultIndex;\n    this.hasParentContext = true;\n  }\n  renderTab(index, label) {\n    if (!this.hasParentContext) {\n      throw new Error('Tabs.Tab must be rendered within a <Tabs> parent container');\n    }\n    return {\n      type: 'TAB_ELEMENT',\n      index,\n      label,\n      isSelected: this.activeIndex === index,\n      ariaSelected: this.activeIndex === index ? 'true' : 'false'\n    };\n  }\n  selectTab(index) {\n    this.activeIndex = index;\n    return this.activeIndex;\n  }\n  getSnapshot() {\n    return {\n      activeIndex: this.activeIndex,\n      selectTab: this.selectTab.bind(this)\n    };\n  }\n}",
    "eHint": "Guard renderTab with hasParentContext check, compute isSelected, and return state snapshot.",
    "eTest": "const tabs = new HeadlessCompoundTabsEngine(0);\n// 1. Initial Render Tab 0\nconst t0 = tabs.renderTab(0, 'Overview');\nif (!t0.isSelected || t0.ariaSelected !== 'true') throw new Error('Initial tab 0 selection failed');\n// 2. Select Tab 1\ntabs.selectTab(1);\nconst t1 = tabs.renderTab(1, 'Billing');\nif (!t1.isSelected || t1.ariaSelected !== 'true') throw new Error('Tab 1 selection update failed');\n// 3. Sub-Component Context Guardrail Test\ntabs.hasParentContext = false;\nlet caught = false;\ntry { tabs.renderTab(0, 'Orphan'); } catch (e) { caught = true; }\nif (!caught) throw new Error('Sub-component outside parent container must throw error');",
    "aTitle": "Native vs Custom Control Evaluator",
    "aDesc": "Implement function evaluateNativeControl(widgetType) returning 'NATIVE' for simple disclosures/modals or 'CUSTOM' for composite widgets.",
    "aStarter": "function evaluateNativeControl(widgetType) {\n  if (widgetType === 'DISCLOSURE' || widgetType === 'SIMPLE_MODAL') return 'NATIVE';\n  return 'CUSTOM';\n}",
    "aHint": "Return 'NATIVE' for DISCLOSURE and SIMPLE_MODAL, else 'CUSTOM'.",
