    "eTitle": "Component Testing & Network Mocking Engine",
    "eDesc": "Implement class ComponentTestingAndMockingEngine evaluating query priority selections, recording simulated userEvent chains, and routing MSW network requests.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Component Testing & Mocking Engine]\nclass ComponentTestingAndMockingEngine {\n  constructor() {\n    this.eventChain = [];\n  }\n  selectQueryStrategy(element) {\n    if (element.role && element.name) {\n      return { priority: 1, query: `getByRole('${element.role}', { name: '${element.name}' })`, type: 'ACCESSIBLE_ROLE' };\n    }\n    if (element.label) {\n      return { priority: 2, query: `getByLabelText('${element.label}')`, type: 'FORM_LABEL' };\n    }\n    if (element.text) {\n      return { priority: 3, query: `getByText('${element.text}')`, type: 'CONTENT_TEXT' };\n    }\n    return { priority: 4, query: `getByTestId('${element.testId}')`, type: 'ESCAPE_HAATCH' };\n  }\n  simulateUserClick(targetName) {\n    this.eventChain = ['pointerover', 'pointerenter', 'pointerdown', 'focus', 'click'];\n    return {\n      target: targetName,\n      events: [...this.eventChain],\n      isHighFidelitySimulation: true\n    };\n  }\n  mockMswNetworkRequest(url, method, env) {\n    const mechanism = env === 'BROWSER' ? 'SERVICE_WORKER' : 'NODE_REQUEST_INTERCEPTION';\n    if (url === '/api/user') {\n      return { status: 200, data: { id: 'usr-1', name: 'Dev' }, mechanism };\n    }\n    return { status: 404, data: { error: 'Not Found' }, mechanism };\n  }\n}",
    "eHint": "Match query priority order, dispatch userEvent chain, and return MSW response with appropriate environment mechanism.",
    "eTest": "const testEngine = new ComponentTestingAndMockingEngine();\n// 1. Query Priority Guidance Evaluation\nconst q1 = testEngine.selectQueryStrategy({ role: 'button', name: 'Submit' });\nif (q1.priority !== 1 || !q1.query.includes('getByRole')) throw new Error('getByRole priority failed');\nconst q4 = testEngine.selectQueryStrategy({ testId: 'canvas' });\nif (q4.priority !== 4 || !q4.query.includes('getByTestId')) throw new Error('getByTestId escape hatch priority failed');\n// 2. High-Fidelity userEvent Simulation\nconst sim = testEngine.simulateUserClick('SaveButton');\nif (sim.events.length !== 5 || sim.events[3] !== 'focus' || sim.events[4] !== 'click') {\n  throw new Error('userEvent click lifecycle simulation failed');\n}\n// 3. MSW Dual-Mode Interception\nconst browserMsw = testEngine.mockMswNetworkRequest('/api/user', 'GET', 'BROWSER');\nif (browserMsw.mechanism !== 'SERVICE_WORKER' || browserMsw.status !== 200) throw new Error('Browser MSW failed');\nconst nodeMsw = testEngine.mockMswNetworkRequest('/api/user', 'GET', 'NODE');\nif (nodeMsw.mechanism !== 'NODE_REQUEST_INTERCEPTION' || nodeMsw.status !== 200) throw new Error('Node MSW failed');",
    "aTitle": "A11y Query Formatter",
