    "eTitle": "Web Vitals Diagnostic & Task Yielding Engine",
    "eDesc": "Implement class WebVitalsAndTaskYieldingEngine evaluating Web Vitals thresholds, running progressive task yielding, and linting PR diffs for architectural regressions.",
    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Web Vitals & Task Yielding Engine]\nclass WebVitalsAndTaskYieldingEngine {\n  constructor() {\n    this.thresholds = { inpGood: 200, lcpGood: 2500, clsGood: 0.1 };\n  }\n  evaluateVitals(metrics) {\n    const isGood = metrics.inp <= this.thresholds.inpGood &&\n                   metrics.lcp <= this.thresholds.lcpGood &&\n                   metrics.cls <= this.thresholds.clsGood;\n    return {\n      metrics,\n      isGood,\n      inpRating: metrics.inp <= 200 ? 'GOOD' : metrics.inp <= 500 ? 'NEEDS_IMPROVEMENT' : 'POOR'\n    };\n  }\n  processChunkedTasks(totalItems, chunkSize) {\n    let yieldCount = 0;\n    let processed = 0;\n    for (let i = 0; i < totalItems; i += chunkSize) {\n      processed += Math.min(chunkSize, totalItems - i);\n      if (i + chunkSize < totalItems) yieldCount++;\n    }\n    return {\n      totalProcessed: processed,\n      yieldCount,\n      mainThreadYielded: yieldCount > 0,\n      strategy: 'PROGRESSIVE_TASK_YIELDING'\n    };\n  }\n  reviewPullRequest(diffCode) {\n    const violations = [];\n    if (diffCode.includes('<div onClick')) violations.push('A11Y_NON_SEMANTIC_CLICK');\n    if (diffCode.includes('{...props}') && diffCode.includes('variant=')) violations.push('PROP_LEAK_CUSTOM_VARIANT');\n    if (diffCode.includes('wrapper.state(')) violations.push('TEST_PRIVATE_STATE_ASSERTION');\n    \n    return {\n      isApproved: violations.length === 0,\n      violations\n    };\n  }\n}",
    "eHint": "Check vitals against thresholds, chunk tasks with yieldCount, and inspect PR diff for violations.",
    "eTest": "const perfEngine = new WebVitalsAndTaskYieldingEngine();\n// 1. Web Vitals Threshold Evaluation\nconst goodVitals = perfEngine.evaluateVitals({ inp: 120, lcp: 2100, cls: 0.05 });\nif (!goodVitals.isGood || goodVitals.inpRating !== 'GOOD') throw new Error('Good Web Vitals evaluation failed');\nconst poorVitals = perfEngine.evaluateVitals({ inp: 600, lcp: 4500, cls: 0.3 });\nif (poorVitals.isGood || poorVitals.inpRating !== 'POOR') throw new Error('Poor Web Vitals evaluation failed');\n// 2. Chunked Task Yielding\nconst chunkRes = perfEngine.processChunkedTasks(1000, 200);\nif (chunkRes.totalProcessed !== 1000 || chunkRes.yieldCount !== 4 || !chunkRes.mainThreadYielded) {\n  throw new Error('Progressive task yielding simulation failed');\n}\n// 3. PR Review Architectural Linting\nconst badPR = '<div onClick={fn} {...props} variant=\"solid\">Button</div>; wrapper.state(\"x\");';\nconst review = perfEngine.reviewPullRequest(badPR);\nif (review.isApproved || review.violations.length !== 3) throw new Error('PR review violation detection failed');",
    "aTitle": "INP Rating Evaluator",
    "aDesc": "Implement function getInpRating(inpMs) returning 'GOOD' for <=200, 'NEEDS_IMPROVEMENT' for <=500, and 'POOR' for >500.",
    "aStarter": "function getInpRating(inpMs) {\n  if (inpMs <= 200) return 'GOOD';\n  if (inpMs <= 500) return 'NEEDS_IMPROVEMENT';\n  return 'POOR';\n}",
    "aHint": "Check inpMs <= 200, <= 500, else POOR.",
