    "eTitle": "Production Relational Catalog Schema & Constraint Engine",
    "eDesc": "Implement function validateCatalogConstraints(merchant, product) verifying referential integrity, positive price checks, and 3VL NULL handling.",
    "eStarter": "// [TEACHING SIMULATION — Relational Catalog Constraint Engine]\nfunction validateCatalogConstraints(merchant, product) {\n  if (!merchant || !merchant.id || !['ACTIVE', 'SUSPENDED'].includes(merchant.status)) {\n    return { valid: false, error: 'INVALID_MERCHANT_CONSTRAINT' };\n  }\n  if (!product || !product.sku || product.price_cents <= 0) {\n    return { valid: false, error: '23514 check_violation: price_cents must be positive' };\n  }\n  if (product.merchant_id !== merchant.id) {\n    return { valid: false, error: '23503 foreign_key_violation: merchant does not exist' };\n  }\n  return { valid: true, error: null };\n}",
    "eHint": "Verify merchant status in ('ACTIVE', 'SUSPENDED'), product price_cents > 0, and merchant_id equals merchant.id.",
    "eTest": "const m = { id: 1, name: 'Apex', status: 'ACTIVE' };\nconst pValid = { id: 10, merchant_id: 1, sku: 'SKU-1', price_cents: 2999 };\nconst pInvalidPrice = { id: 11, merchant_id: 1, sku: 'SKU-2', price_cents: -50 };\nconst pInvalidFk = { id: 12, merchant_id: 999, sku: 'SKU-3', price_cents: 1000 };\n\nif (!validateCatalogConstraints(m, pValid).valid) throw new Error('Valid catalog entry failed');\nif (validateCatalogConstraints(m, pInvalidPrice).valid || !validateCatalogConstraints(m, pInvalidPrice).error.includes('23514')) throw new Error('Check constraint violation failed');\nif (validateCatalogConstraints(m, pInvalidFk).valid || !validateCatalogConstraints(m, pInvalidFk).error.includes('23503')) throw new Error('Foreign key violation failed');",
    "aTitle": "Three-Valued Logic Predicate Evaluator",
