    "eTitle": "Executive Analytical Query & Window Processing Engine",
    "eDesc": "Implement function executeAnalyticsPipeline(users, orders) calculating customer running spend totals, sequential order numbers, and anti-join zero-order users.",
    "eStarter": "// [TEACHING SIMULATION — Analytical Query & Window Processing Engine]\nfunction executeAnalyticsPipeline(users, orders) {\n  // 1. Anti-Join: Users with zero orders\n  const activeUserIds = new Set(orders.map(o => o.userId));\n  const zeroOrderUsers = users.filter(u => !activeUserIds.has(u.id));\n\n  // 2. Window processing: Running totals & sequence per user\n  const windowedOrders = [];\n  const userOrderGroups = new Map();\n  for (const o of orders) {\n    if (!userOrderGroups.has(o.userId)) userOrderGroups.set(o.userId, []);\n    userOrderGroups.get(o.userId).push(o);\n  }\n\n  for (const [userId, userOrders] of userOrderGroups.entries()) {\n    userOrders.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());\n    let runningTotal = 0;\n    userOrders.forEach((o, idx) => {\n      runningTotal += o.amount;\n      const prevAmount = idx > 0 ? userOrders[idx - 1].amount : null;\n      windowedOrders.push({\n        orderId: o.id,\n        userId,\n        seq: idx + 1,\n        amount: o.amount,\n        runningTotal,\n        prevAmount\n      });\n    });\n  }\n\n  return { zeroOrderUsers, windowedOrders };\n}",
    "eHint": "Compute zeroOrderUsers via anti-join, then sort orders and calculate runningTotal and prevAmount per user partition.",
    "eTest": "const users = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }, { id: 3, name: 'Charlie' }];\nconst orders = [\n  { id: 101, userId: 1, amount: 100, createdAt: '2026-01-01' },\n  { id: 102, userId: 1, amount: 150, createdAt: '2026-01-02' },\n  { id: 103, userId: 2, amount: 50,  createdAt: '2026-01-01' }\n];\nconst res = executeAnalyticsPipeline(users, orders);\nif (res.zeroOrderUsers.length !== 1 || res.zeroOrderUsers[0].name !== 'Charlie') throw new Error('Anti-join failed');\nconst alice2nd = res.windowedOrders.find(o => o.orderId === 102);\nif (alice2nd.seq !== 2 || alice2nd.runningTotal !== 250 || alice2nd.prevAmount !== 100) throw new Error('Window calculations failed');",
    "aTitle": "SQL Anti-Join Predicate Validator",
    "aDesc": "Implement function isAntiJoinMatch(foreignKeyVal) returning boolean.",
    "aStarter": "function isAntiJoinMatch(foreignKeyVal) {\n  return foreignKeyVal === null || foreignKeyVal === undefined;\n}",
    "aHint": "Return foreignKeyVal === null || foreignKeyVal === undefined.",
    "aTest": "if (!isAntiJoinMatch(null)) throw new Error('null should match anti-join');\nif (isAntiJoinMatch(123)) throw new Error('Existing ID should not match anti-join');"
