    "eStarter": "export interface AbacSubject { id: string; department: string; clearance: number; }\nexport interface AbacResource { id: string; department: string; classification: number; status: 'DRAFT' | 'PUBLISHED'; }\nexport interface AbacEnvironment { hour: number; ipSubnet: string; }\n\nexport class AbacPolicyEngine {\n  evaluate(sub: AbacSubject, res: AbacResource, action: 'READ' | 'WRITE', env: AbacEnvironment): { allow: boolean; reason?: string } {\n    if (action === 'WRITE') {\n      if (sub.department !== res.department) return { allow: false, reason: 'DEPARTMENT_MISMATCH' };\n      if (res.status !== 'DRAFT') return { allow: false, reason: 'RESOURCE_LOCKED' };\n      if (env.hour < 9 || env.hour > 18) return { allow: false, reason: 'OUTSIDE_BUSINESS_HOURS' };\n      if (!env.ipSubnet.startsWith('10.')) return { allow: false, reason: 'EXTERNAL_SUBNET_FORBIDDEN' };\n    }\n    if (sub.clearance < res.classification) return { allow: false, reason: 'INSUFFICIENT_CLEARANCE' };\n    return { allow: true };\n  }\n}",
