    "eTest": "import { AbacPolicyEngine } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const engine = new AbacPolicyEngine();\n  const sub = { id: 'u1', department: 'Engineering', clearance: 3 };\n  const resDraft = { id: 'd1', department: 'Engineering', classification: 2, status: 'DRAFT' as const };\n  const resPublished = { id: 'd2', department: 'Engineering', classification: 2, status: 'PUBLISHED' as const };\n\n  assert.strictEqual(engine.evaluate(sub, resDraft, 'WRITE', { hour: 14, ipSubnet: '10.0.1.0/24' }).allow, true);\n  assert.strictEqual(engine.evaluate(sub, resPublished, 'WRITE', { hour: 14, ipSubnet: '10.0.1.0/24' }).allow, false);\n  assert.strictEqual(engine.evaluate(sub, resDraft, 'WRITE', { hour: 22, ipSubnet: '10.0.1.0/24' }).allow, false);\n  assert.strictEqual(engine.evaluate(sub, resDraft, 'WRITE', { hour: 14, ipSubnet: '198.51.100.0/24' }).allow, false);\n  assert.strictEqual(engine.evaluate({ ...sub, clearance: 1 }, resDraft, 'READ', { hour: 14, ipSubnet: '10.0.1.0/24' }).allow, false);\n  console.log('✅ Day 90 Exam Passed!');\n}",
