    "eTitle": "Day 91 Exam: Session-Bound HMAC-SHA256 Double Submit CSRF Validator",
    "eDesc": "Implement class DoubleSubmitCsrfValidator with session binding, pre-comparison length checks, and timing-safe verification.",
    "eStarter": "import crypto from 'crypto';\n\nexport class DoubleSubmitCsrfValidator {\n  constructor(private secretKey: string) {}\n\n  generateToken(sessionId: string): string {\n    const raw = crypto.randomBytes(16).toString('hex');\n    const sig = crypto.createHmac('sha256', this.secretKey).update(sessionId + ':' + raw).digest('hex');\n    return raw + '.' + sig;\n  }\n\n  validate(cookieToken: unknown, headerToken: unknown, activeSessionId: string): { valid: boolean; code: string } {\n    if (!cookieToken || !headerToken) return { valid: false, code: 'CSRF_TOKEN_MISSING' };\n    if (typeof cookieToken !== 'string' || typeof headerToken !== 'string') return { valid: false, code: 'CSRF_TOKEN_MALFORMED' };\n    if (cookieToken.length !== headerToken.length) return { valid: false, code: 'CSRF_TOKEN_WRONG_LENGTH' };\n\n    const cookieBuf = Buffer.from(cookieToken);\n    const headerBuf = Buffer.from(headerToken);\n    if (!crypto.timingSafeEqual(cookieBuf, headerBuf)) return { valid: false, code: 'CSRF_TOKEN_TAMPERED' };\n\n    const parts = headerToken.split('.');\n    if (parts.length !== 2) return { valid: false, code: 'CSRF_TOKEN_MALFORMED' };\n    const [raw, sig] = parts;\n    const expectedSig = crypto.createHmac('sha256', this.secretKey).update(activeSessionId + ':' + raw).digest('hex');\n    if (sig.length !== expectedSig.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {\n      return { valid: false, code: 'CSRF_SESSION_MISMATCH' };\n    }\n    return { valid: true, code: 'OK' };\n  }\n}",
    "eHint": "Ensure the token is bound to activeSessionId using HMAC-SHA256, verify string lengths match before converting to buffers, and validate with timingSafeEqual.",
    "eTest": "import { DoubleSubmitCsrfValidator } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const validator = new DoubleSubmitCsrfValidator('top-secret-signing-key');\n  const tokenUser1 = validator.generateToken('session_alpha');\n\n  assert.strictEqual(validator.validate(tokenUser1, tokenUser1, 'session_alpha').code, 'OK');\n  assert.strictEqual(validator.validate(undefined, tokenUser1, 'session_alpha').code, 'CSRF_TOKEN_MISSING');\n  assert.strictEqual(validator.validate(tokenUser1, 'short', 'session_alpha').code, 'CSRF_TOKEN_WRONG_LENGTH');\n  assert.strictEqual(validator.validate(tokenUser1, tokenUser1, 'session_beta').code, 'CSRF_SESSION_MISMATCH');\n  assert.strictEqual(validator.validate(tokenUser1, tokenUser1.slice(0, -1) + '0', 'session_alpha').code, 'CSRF_TOKEN_TAMPERED');\n  console.log('✅ Day 91 Exam Passed!');\n}",
    "aTitle": "Day 91 Assignment: W3C CSP Level 3 Header Generator & Nonce Injector",
    "aDesc": "Implement function generateStrictCspHeader(nonce: string): string generating strict CSP3 directives without 'unsafe-inline'.",
