    "eTitle": "Day 92 Exam: AES-256-GCM AAD Envelope Encryption Module",
    "eDesc": "Implement class EnvelopeEncryptionEngine supporting encryptField(plaintext, context) and decryptField(payload, context) with AAD binding and best-effort Buffer.fill(0) memory hygiene.",
    "eStarter": "import crypto from 'crypto';\n\nexport interface SecurityContext {\n  tenantId: string;\n  recordId: string;\n  fieldName: string;\n  version: number;\n}\n\nexport class EnvelopeEncryptionEngine {\n  constructor(private masterKek: Buffer) {}\n\n  encryptField(plaintext: string, ctx: SecurityContext): { encryptedDek: string; iv: string; ciphertext: string; authTag: string } {\n    const rawDek = crypto.randomBytes(32);\n    const dataIv = crypto.randomBytes(12);\n    const aad = `${ctx.tenantId}:${ctx.recordId}:${ctx.fieldName}:${ctx.version}`;\n\n    const dataCipher = crypto.createCipheriv('aes-256-gcm', rawDek, dataIv);\n    dataCipher.setAAD(Buffer.from(aad, 'utf8'));\n    const ciphertext = Buffer.concat([dataCipher.update(plaintext, 'utf8'), dataCipher.final()]);\n    const authTag = dataCipher.getAuthTag();\n\n    const kekIv = crypto.randomBytes(12);\n    const kekCipher = crypto.createCipheriv('aes-256-gcm', this.masterKek, kekIv);\n    const wrappedDek = Buffer.concat([kekCipher.update(rawDek), kekCipher.final()]);\n    const wrappedTag = kekCipher.getAuthTag();\n    const encryptedDekCombined = kekIv.toString('hex') + ':' + wrappedTag.toString('hex') + ':' + wrappedDek.toString('hex');\n\n    rawDek.fill(0); // Best-effort plaintext DEK memory hygiene\n    return {\n      encryptedDek: encryptedDekCombined,\n      iv: dataIv.toString('hex'),\n      ciphertext: ciphertext.toString('hex'),\n      authTag: authTag.toString('hex')\n    };\n  }\n\n  decryptField(payload: { encryptedDek: string; iv: string; ciphertext: string; authTag: string }, ctx: SecurityContext): string {\n    const [kekIvHex, kekTagHex, wrappedHex] = payload.encryptedDek.split(':');\n    const kekDecipher = crypto.createDecipheriv('aes-256-gcm', this.masterKek, Buffer.from(kekIvHex, 'hex'));\n    kekDecipher.setAuthTag(Buffer.from(kekTagHex, 'hex'));\n    const rawDek = Buffer.concat([kekDecipher.update(Buffer.from(wrappedHex, 'hex')), kekDecipher.final()]);\n\n    const aad = `${ctx.tenantId}:${ctx.recordId}:${ctx.fieldName}:${ctx.version}`;\n    try {\n      const dataDecipher = crypto.createDecipheriv('aes-256-gcm', rawDek, Buffer.from(payload.iv, 'hex'));\n      dataDecipher.setAuthTag(Buffer.from(payload.authTag, 'hex'));\n      dataDecipher.setAAD(Buffer.from(aad, 'utf8'));\n      const plaintext = Buffer.concat([dataDecipher.update(Buffer.from(payload.ciphertext, 'hex')), dataDecipher.final()]).toString('utf8');\n      return plaintext;\n    } finally {\n      rawDek.fill(0); // Best-effort plaintext DEK memory hygiene\n    }\n  }\n}",
    "eHint": "Construct the Additional Authenticated Data string from context attributes, use 12-byte random IVs, set AAD on both ciphers, and zero rawDek buffers.",
    "eTest": "import { EnvelopeEncryptionEngine } from './solution';\nimport crypto from 'crypto';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const kek = crypto.randomBytes(32);\n  const engine = new EnvelopeEncryptionEngine(kek);\n  const ctxAlpha = { tenantId: 'ten_alpha', recordId: 'rec_100', fieldName: 'ssn', version: 1 };\n  const ctxBeta = { tenantId: 'ten_beta', recordId: 'rec_100', fieldName: 'ssn', version: 1 };\n\n  const encrypted = engine.encryptField('987-65-4321', ctxAlpha);\n  assert.strictEqual(engine.decryptField(encrypted, ctxAlpha), '987-65-4321');\n\n  // Assert ciphertext transplant across tenants fails authentication\n  assert.throws(() => {\n    engine.decryptField(encrypted, ctxBeta);\n  }, /authenticate data/);\n\n  console.log('✅ Day 92 Exam Passed!');\n}",
    "aTitle": "Day 92 Assignment: Zero-Knowledge DEK Re-Wrapper & Key Rotator",
    "aDesc": "Implement function rewrapDataEncryptionKey(encryptedDekHex: string, oldKek: Buffer, newKek: Buffer): string that re-encrypts DEKs without touching payload.",
    "aStarter": "import crypto from 'crypto';\n\nexport function rewrapDataEncryptionKey(encryptedDekHex: string, oldKek: Buffer, newKek: Buffer): string {\n  const [ivHex, tagHex, wrappedHex] = encryptedDekHex.split(':');\n  const d = crypto.createDecipheriv('aes-256-gcm', oldKek, Buffer.from(ivHex, 'hex'));\n  d.setAuthTag(Buffer.from(tagHex, 'hex'));\n  const rawDek = Buffer.concat([d.update(Buffer.from(wrappedHex, 'hex')), d.final()]);\n\n  const newIv = crypto.randomBytes(12);\n  const c = crypto.createCipheriv('aes-256-gcm', newKek, newIv);\n  const rewrapped = Buffer.concat([c.update(rawDek), c.final()]);\n  const newTag = c.getAuthTag();\n\n  rawDek.fill(0); // Best-effort plaintext DEK memory hygiene\n  return newIv.toString('hex') + ':' + newTag.toString('hex') + ':' + rewrapped.toString('hex');\n}",
    "aHint": "Decrypt the Data Encryption Key using oldKek, immediately re-encrypt it under newKek with a fresh random 12-byte IV, and overwrite the plaintext buffer.",
    "aTest": "import { rewrapDataEncryptionKey } from './solution';\nimport crypto from 'crypto';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const oldKek = crypto.randomBytes(32);\n  const newKek = crypto.randomBytes(32);\n  const rawDek = crypto.randomBytes(32);\n\n  const iv = crypto.randomBytes(12);\n  const c = crypto.createCipheriv('aes-256-gcm', oldKek, iv);\n  const ct = Buffer.concat([c.update(rawDek), c.final()]);\n  const tag = c.getAuthTag();\n  const initial = iv.toString('hex') + ':' + tag.toString('hex') + ':' + ct.toString('hex');\n\n  const rewrapped = rewrapDataEncryptionKey(initial, oldKek, newKek);\n  assert.notStrictEqual(initial, rewrapped);\n\n  // Verify unwrapping with newKek yields rawDek\n  const [newIvHex, newTagHex, newWrappedHex] = rewrapped.split(':');\n  const d = crypto.createDecipheriv('aes-256-gcm', newKek, Buffer.from(newIvHex, 'hex'));\n  d.setAuthTag(Buffer.from(newTagHex, 'hex'));\n  const unwrapped = Buffer.concat([d.update(Buffer.from(newWrappedHex, 'hex')), d.final()]);\n  assert.deepStrictEqual(unwrapped, rawDek);\n\n  console.log('✅ Day 92 Assignment Passed!');\n}"
