    "eDesc": "Implement class InMemoryOrderRepo with save(order) and findById(id) using a Map, and verify that OrderService creates and saves orders with accurate subtotal and tax calculations without external I/O.",
    "eStarter": "export interface OrderItem { price: number; }\nexport interface Order { id: string; items: OrderItem[]; subtotal: number; total: number; status: string; }\n\nexport class InMemoryOrderRepo {\n  private orders = new Map<string, Order>();\n  async save(order: Order): Promise<void> {\n    this.orders.set(order.id, { ...order });\n  }\n  async findById(id: string): Promise<Order | null> {\n    return this.orders.get(id) || null;\n  }\n}\n\nexport class OrderService {\n  constructor(private repo: InMemoryOrderRepo, private taxRate: number) {}\n  async createOrder(id: string, items: OrderItem[]): Promise<Order> {\n    const subtotal = items.reduce((s, i) => s + i.price, 0);\n    const total = subtotal * (1 + this.taxRate);\n    const order: Order = { id, items, subtotal, total, status: 'PENDING' };\n    await this.repo.save(order);\n    return order;\n  }\n}",
    "eHint": "Ensure the save method stores an isolated copy of the order within the in-memory Map data structure so that subsequent external mutations cannot corrupt internal repository state.",
    "eTest": "import { InMemoryOrderRepo, OrderService } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const repo = new InMemoryOrderRepo();\n  const service = new OrderService(repo, 0.10);\n  const created = await service.createOrder('ord-1', [{ price: 100 }, { price: 50 }]);\n  assert.strictEqual(created.subtotal, 150);\n  assert.strictEqual(created.total, 165);\n  assert.strictEqual(created.status, 'PENDING');\n\n  const fetched = await repo.findById('ord-1');\n  assert.ok(fetched !== null);\n  assert.strictEqual(fetched?.total, 165);\n  console.log('✅ Day 93 Exam Passed!');\n}",
