    "aStarter": "export class TestcontainerConnectionManager {\n  constructor(public port: number, private maxRetries: number = 5) {}\n  async connectWithBackoff<T>(connectFn: () => Promise<T>): Promise<T> {\n    let lastErr: any;\n    for (let attempt = 0; attempt < this.maxRetries; attempt++) {\n      try {\n        return await connectFn();\n      } catch (err) {\n        lastErr = err;\n        await new Promise(r => setTimeout(r, 10 * Math.pow(2, attempt)));\n      }\n    }\n    throw lastErr;\n  }\n}",
