    "aTest": "import { TestcontainerConnectionManager } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const mgr = new TestcontainerConnectionManager(49152, 4);\n  let attempts = 0;\n  const result = await mgr.connectWithBackoff(async () => {\n    attempts++;\n    if (attempts < 3) throw new Error('Port not listening yet');\n    return { connected: true, port: mgr.port };\n  });\n\n  assert.strictEqual(result.connected, true);\n  assert.strictEqual(result.port, 49152);\n  assert.strictEqual(attempts, 3);\n  console.log('✅ Day 94 Assignment Passed!');\n}"
