    "eTitle": "Day 96 Exam: Deterministic Auto-Waiting Actionability Poller",
    "eDesc": "Implement function waitForActionableCondition(predicateFn, timeoutMs, intervalMs) that polls a condition deterministically without hardcoded sleep delays.",
    "eStarter": "export async function waitForActionableCondition(\n  predicateFn: () => boolean,\n  timeoutMs: number = 1000,\n  intervalMs: number = 10\n): Promise<{ passed: boolean; elapsedMs: number }> {\n  const start = Date.now();\n  while (Date.now() - start < timeoutMs) {\n    if (predicateFn()) {\n      return { passed: true, elapsedMs: Date.now() - start };\n    }\n    await new Promise(r => setTimeout(r, intervalMs));\n  }\n  return { passed: false, elapsedMs: Date.now() - start };\n}",
    "eHint": "Continuously check the predicate function at the specified interval, returning elapsed latency immediately when true to eliminate wasteful fixed sleep pauses.",
    "eTest": "import { waitForActionableCondition } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  let ready = false;\n  setTimeout(() => { ready = true; }, 40);\n\n  const res = await waitForActionableCondition(() => ready, 500, 10);\n  assert.strictEqual(res.passed, true);\n  assert.ok(res.elapsedMs >= 30 && res.elapsedMs <= 300);\n\n  const failRes = await waitForActionableCondition(() => false, 100, 10);\n  assert.strictEqual(failRes.passed, false);\n  console.log('✅ Day 96 Exam Passed!');\n}",
    "aTitle": "Day 96 Assignment: Automated Flaky Test Detector & Quarantine Governance Engine",
    "aDesc": "Implement class FlakyTestQuarantineGovernor that executes tests across multiple iterations, identifies non-deterministic tests, and attaches governance metadata.",
    "aStarter": "export interface QuarantineRecord {\n  testId: string;\n  status: 'QUARANTINED';\n  owner: string;\n  issue: string;\n  slaDays: number;\n  passRate: number;\n}\n\nexport class FlakyTestQuarantineGovernor {\n  public quarantined: QuarantineRecord[] = [];\n  constructor(public iterations: number = 10) {}\n  async evaluateTest(testId: string, testFn: () => Promise<boolean>, owner: string, issue: string): Promise<{ isFlaky: boolean; passRate: number }> {\n    let passed = 0;\n    for (let i = 0; i < this.iterations; i++) {\n      try {\n        if (await testFn()) passed++;\n      } catch {}\n    }\n    const passRate = passed / this.iterations;\n    const isFlaky = passRate > 0 && passRate < 1;\n    if (isFlaky) {\n      this.quarantined.push({\n        testId,\n        status: 'QUARANTINED',\n        owner,\n        issue,\n        slaDays: 7,\n        passRate\n      });\n    }\n    return { isFlaky, passRate };\n  }\n}",
    "aHint": "Evaluate the test across all iterations, detecting intermittent results where pass rate is between zero and one, and attach assigned owner and ticket SLA metadata.",
    "aTest": "import { FlakyTestQuarantineGovernor } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const gov = new FlakyTestQuarantineGovernor(10);\n  let counter = 0;\n  const intermittentFn = async () => {\n    counter++;\n    return counter % 2 === 0;\n  };\n\n  const report = await gov.evaluateTest('test-checkout-cart', intermittentFn, 'checkout-team', 'CHK-902');\n  assert.strictEqual(report.isFlaky, true);\n  assert.strictEqual(gov.quarantined.length, 1);\n  assert.strictEqual(gov.quarantined[0].owner, 'checkout-team');\n  assert.strictEqual(gov.quarantined[0].slaDays, 7);\n  console.log('✅ Day 96 Assignment Passed!');\n}"
