    "eTitle": "Day 98 Exam: Linux Virtual Filesystem /proc Diagnostic Status Parser",
    "eDesc": "Implement function parseLinuxProcStatus(rawContent: string) that parses /proc/[pid]/status key-value lines and extracts Name, State, Pid, and VmRssKb.",
    "eStarter": "export function parseLinuxProcStatus(rawContent: string): { name: string; state: string; pid: number; vmRssKb: number } {\n  const lines = rawContent.split('\\n');\n  const map: Record<string, string> = {};\n  for (const line of lines) {\n    const parts = line.split(':');\n    if (parts.length >= 2) {\n      map[parts[0].trim()] = parts.slice(1).join(':').trim();\n    }\n  }\n  const rssMatch = (map['VmRSS'] || '0').match(/\\d+/);\n  return {\n    name: map['Name'] || '',\n    state: map['State'] || '',\n    pid: parseInt(map['Pid'] || '0', 10),\n    vmRssKb: rssMatch ? parseInt(rssMatch[0], 10) : 0\n  };\n}",
    "eHint": "Parse colon-delimited lines from the virtual status file, extracting key values and converting numeric memory statistics like VmRSS into integer kilobyte values.",
    "eTest": "import { parseLinuxProcStatus } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const sample = \"Name:\\tnode-api\\nState:\\tS (sleeping)\\nPid:\\t2048\\nVmRSS:\\t   65536 kB\";\n  const res = parseLinuxProcStatus(sample);\n  assert.strictEqual(res.name, 'node-api');\n  assert.strictEqual(res.pid, 2048);\n  assert.strictEqual(res.vmRssKb, 65536);\n  assert.strictEqual(res.state, 'S (sleeping)');\n  console.log('✅ Day 98 Exam Passed!');\n}",
    "aTitle": "Day 98 Assignment: Resilient Systemd Service Unit Generator & Signal Escalation Gate",
    "aDesc": "Implement class SystemdServiceUnitBuilder that generates valid Systemd unit files with Type=exec or Type=notify, unprivileged user, and graceful SIGTERM shutdown.",
    "aStarter": "export class SystemdServiceUnitBuilder {\n  constructor(\n    public name: string,\n    public execStart: string,\n    public type: 'exec' | 'notify' = 'exec',\n    public user: string = 'node'\n  ) {}\n  generateUnitFile(): string {\n    return [\n      '[Unit]',\n      `Description=${this.name} Production Service`,\n      'After=network.target',\n      '',\n      '[Service]',\n      `Type=${this.type}`,\n      `ExecStart=${this.execStart}`,\n      `User=${this.user}`,\n      'Restart=on-failure',\n      'RestartSec=5s',\n      'TimeoutStopSec=30s',\n      'KillSignal=SIGTERM',\n      '',\n      '[Install]',\n      'WantedBy=multi-user.target'\n    ].join('\\n');\n  }\n}",
    "aHint": "Assemble standard INI format directives for Unit, Service, and Install sections, specifying the execution type, unprivileged user account, and graceful termination signal.",
    "aTest": "import { SystemdServiceUnitBuilder } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  const builder = new SystemdServiceUnitBuilder('payment-service', '/usr/bin/node /app/dist/server.js', 'exec', 'node');\n  const unit = builder.generateUnitFile();\n  assert.ok(unit.includes('Type=exec'));\n  assert.ok(unit.includes('User=node'));\n  assert.ok(unit.includes('KillSignal=SIGTERM'));\n  assert.ok(unit.includes('WantedBy=multi-user.target'));\n  console.log('✅ Day 98 Assignment Passed!');\n}"
