    "eStarter": "// Day 100 Explorer: Docker Compose v2 Topology & Port Validator\nexport interface ComposeService {\n  image: string;\n  networks?: string[];\n  ports?: string[];\n  expose?: string[];\n}\n\nexport interface ComposeFile {\n  services: Record<string, ComposeService>;\n  networks?: Record<string, any>;\n}\n\nexport class ComposeTopologyValidator {\n  constructor(private readonly config: ComposeFile) {}\n\n  public isPortReachableFromHost(serviceName: string, targetPort: number): boolean {\n    // Return true only if service publishes the target port to host\n    return false;\n  }\n\n  public canContainersCommunicate(serviceA: string, serviceB: string): boolean {\n    // Check if services share either the default network or any custom network\n    return false;\n  }\n}",
