    "eTest": "import { ComposeTopologyValidator } from './starter';\n\nconst validConfig = {\n  services: {\n    web: {\n      image: 'node:24-alpine',\n      ports: ['3000:3000'],\n      networks: ['frontend_net']\n    },\n    api: {\n      image: 'node:24-alpine',\n      networks: ['frontend_net', 'backend_net'],\n      expose: ['8080']\n    },\n    db: {\n      image: 'postgres:18-alpine',\n      expose: ['5432'],\n      networks: ['backend_net']\n    }\n  },\n  networks: {\n    frontend_net: {},\n    backend_net: {}\n  }\n};\n\nconst validator = new ComposeTopologyValidator(validConfig);\nif (!validator.isPortReachableFromHost('web', 3000)) throw new Error('Web port 3000 should be reachable from host');\nif (validator.isPortReachableFromHost('db', 5432)) throw new Error('DB port 5432 must NOT be reachable from host');\nif (!validator.canContainersCommunicate('web', 'api')) throw new Error('Web and API should communicate via frontend_net');\nif (validator.canContainersCommunicate('web', 'db')) throw new Error('Web and DB must be isolated across different networks');\nif (!validator.canContainersCommunicate('api', 'db')) throw new Error('API and DB should communicate via backend_net');\nconsole.log('Day 100 Explorer tests passed successfully.');",
    "aTitle": "Compose Orchestrated Healthchecks & Custom Bridge Segmentation",
    "aDesc": "Implement a robust Compose startup orchestrator that prevents container startup race conditions. Model `depends_on` with `{ condition: 'service_healthy' }` linked to active container healthcheck probes (`pg_isready -U postgres`), ensuring dependent services are never launched until database engines are fully initialized.",
    "aStarter": "// Day 100 Architect: Compose Healthcheck Dependency State Machine\nexport interface HealthcheckConfig {\n  test: string[];\n  intervalMs: number;\n  timeoutMs: number;\n  retries: number;\n}\n\nexport interface ServiceNode {\n  name: string;\n  healthcheck?: HealthcheckConfig;\n  dependsOn?: Record<string, { condition: 'service_healthy' | 'service_started' }>;\n}\n\nexport class ComposeStartupCoordinator {\n  private serviceHealth = new Map<string, 'starting' | 'healthy' | 'unhealthy'>();\n\n  public registerService(service: ServiceNode): void {\n    // Register service initial state\n  }\n\n  public markHealthy(serviceName: string): void {\n    // Transition service to healthy\n  }\n\n  public canStartService(serviceName: string, serviceList: ServiceNode[]): boolean {\n    // Return true only if all depends_on condition requirements are satisfied\n    return false;\n  }\n}",
    "aHint": "Locate the target service in the service list and examine its dependencies map. If a dependency specifies the service_healthy condition, verify that the dependency service is currently marked healthy in the state map. If a dependency only requires service_started, confirm that the dependency is present.",
    "aTest": "import { ComposeStartupCoordinator, ServiceNode } from './starter';\n\nconst coordinator = new ComposeStartupCoordinator();\nconst services: ServiceNode[] = [\n  {\n    name: 'db',\n    healthcheck: { test: ['CMD', 'pg_isready'], intervalMs: 500, timeoutMs: 200, retries: 3 }\n  },\n  {\n    name: 'api',\n    dependsOn: { db: { condition: 'service_healthy' } }\n  }\n];\n\ncoordinator.registerService(services[0]);\ncoordinator.registerService(services[1]);\n\nif (coordinator.canStartService('api', services)) throw new Error('API must not start while DB is only starting');\ncoordinator.markHealthy('db');\nif (!coordinator.canStartService('api', services)) throw new Error('API should be allowed to start once DB is healthy');\nconsole.log('Day 100 Architect tests passed successfully.');"
