    "eTitle": "PACELC Configuration Classifier & Trade-off Analyzer",
    "eDescription": "Implement `function evaluatePACELC(configurationSpec)` parsing distributed storage parameters to determine partition behavior and normal-state latency/consistency trade-offs.",
    "eStarterCode": "function evaluatePACELC(config) {\n  // config: { engine, syncReplication: boolean, majorityQuorum: boolean, clientTimeoutMs: number }\n  // Return { pacelcCode: string, partitionChoice: 'A' | 'C', normalChoice: 'L' | 'C', rationale: string }\n  return { pacelcCode: 'PC/EC', partitionChoice: 'C', normalChoice: 'C', rationale: '' };\n}\n\nmodule.exports = { evaluatePACELC };",
    "eSolutionCode": "function evaluatePACELC(config) {\n  const { engine, syncReplication, majorityQuorum, clientTimeoutMs } = config;\n\n  const partitionChoice = (syncReplication || majorityQuorum) ? 'C' : 'A';\n  const normalChoice = (syncReplication && majorityQuorum) ? 'C' : (syncReplication ? 'C' : 'L');\n\n  const pacelcCode = `P${partitionChoice}/E${normalChoice}`;\n  const rationale = partitionChoice === 'C'\n    ? `Under network partition, ${engine} enforces consistency by rejecting writes that lack majority acknowledgment. Under normal operation, it trades off ${normalChoice === 'C' ? 'latency for strong consistency' : 'consistency for lower latency'}.`\n    : `Under network partition, ${engine} accepts writes locally to preserve availability, trading off consistency. In normal operation, it provides low latency via asynchronous replication.`;\n\n  return { pacelcCode, partitionChoice, normalChoice, rationale };\n}\n\nmodule.exports = { evaluatePACELC };",
    "eHint1": "Assess the partition choice based on whether the configuration requires majority quorum or synchronous replication to acknowledge writes successfully.",
    "eHint2": "For normal non-partitioned operation, check whether the engine waits for synchronous replica acknowledgments (Consistency) or returns as soon as the local node commits (Latency).",
    "eTestCode": "const { evaluatePACELC } = require('./solution');\nconst res1 = evaluatePACELC({ engine: 'Cassandra-One', syncReplication: false, majorityQuorum: false, clientTimeoutMs: 500 });\nconsole.assert(res1.pacelcCode === 'PA/EL', 'Cassandra ONE should evaluate to PA/EL');\n\nconst res2 = evaluatePACELC({ engine: 'PostgreSQL-Sync', syncReplication: true, majorityQuorum: true, clientTimeoutMs: 5000 });\nconsole.assert(res2.pacelcCode === 'PC/EC', 'Postgres Sync should evaluate to PC/EC');\nconsole.log('Day 110 Explorer Tests Passed!');",
    "aTitle": "Quorum Consensus Simulator with Version Overlap Verification",
    "aDescription": "Implement `class QuorumConsensusSimulator` with N nodes verifying that overlapping quorums (W + R > N) prevent stale reads under version tracking, while weak quorums yield stale data.",
    "aStarterCode": "class QuorumConsensusSimulator {\n  constructor(totalNodes = 5, writeQuorum = 3, readQuorum = 3) {\n    this.totalNodes = totalNodes;\n    this.writeQuorum = writeQuorum;\n    this.readQuorum = readQuorum;\n    this.nodes = Array.from({ length: totalNodes }, (_, i) => ({ id: i, version: 0, value: null }));\n  }\n\n  write(value, targetNodeIds) {\n    // TODO: Write value to targetNodeIds incrementing version if target count >= writeQuorum\n  }\n\n  read(targetNodeIds) {\n    // TODO: Read from targetNodeIds; return highest version found\n  }\n}\n\nmodule.exports = { QuorumConsensusSimulator };",
    "aSolutionCode": "class QuorumConsensusSimulator {\n  constructor(totalNodes = 5, writeQuorum = 3, readQuorum = 3) {\n    this.totalNodes = totalNodes;\n    this.writeQuorum = writeQuorum;\n    this.readQuorum = readQuorum;\n    this.currentGlobalVersion = 0;\n    this.nodes = Array.from({ length: totalNodes }, (_, i) => ({ id: i, version: 0, value: null }));\n  }\n\n  write(value, targetNodeIds) {\n    if (targetNodeIds.length < this.writeQuorum) {\n      return { success: false, reason: 'Failed to meet write quorum threshold' };\n    }\n    this.currentGlobalVersion++;\n    const version = this.currentGlobalVersion;\n\n    for (const id of targetNodeIds) {\n      if (id >= 0 && id < this.totalNodes) {\n        this.nodes[id] = { id, version, value };\n      }\n    }\n    return { success: true, version, writtenTo: targetNodeIds.length };\n  }\n\n  read(targetNodeIds) {\n    if (targetNodeIds.length < this.readQuorum) {\n      return { success: false, reason: 'Failed to meet read quorum threshold' };\n    }\n\n    const responses = targetNodeIds\n      .filter(id => id >= 0 && id < this.totalNodes)\n      .map(id => this.nodes[id]);\n\n    let highest = responses[0];\n    for (const r of responses) {\n      if (r.version > highest.version) {\n        highest = r;\n      }\n    }\n\n    const isLatest = highest.version === this.currentGlobalVersion;\n    return {\n      success: true,\n      version: highest.version,\n      value: highest.value,\n      isLatest\n    };\n  }\n}\n\nmodule.exports = { QuorumConsensusSimulator };",
    "aHint1": "Assign a monotonically increasing version number to every write operation that successfully meets or exceeds the required write quorum size.",
    "aHint2": "When reading, collect the responses from the specified node IDs and locate the record possessing the maximum version number. Compare that version against the latest global write version.",
    "aTestCode": "const { QuorumConsensusSimulator } = require('./solution');\nconst simStrong = new QuorumConsensusSimulator(5, 3, 3);\nsimStrong.write('order_v1', [0, 1, 2]);\nconst readStrong = simStrong.read([2, 3, 4]);\nconsole.assert(readStrong.isLatest === true && readStrong.value === 'order_v1', 'Strong quorum must observe latest write');\n\nconst simWeak = new QuorumConsensusSimulator(5, 2, 2);\nsimWeak.write('order_v1', [0, 1]);\nconst readWeak = simWeak.read([2, 3]);\nconsole.assert(readWeak.isLatest === false, 'Weak quorum can read stale or empty state');\nconsole.log('Day 110 Architect Tests Passed!');"
