    "eTitle": "Quantitative Platform Capacity & Traffic Profiler",
    "eDescription": "Implement `function calculatePlatformCapacity(spec)` taking DAU, actions/day, read/write ratio, payload sizes, and burst multipliers; outputting traffic and storage metrics.",
    "eStarterCode": "function calculatePlatformCapacity(spec) {\n  // spec: { dau, actionsPerUser, readRatio, burstMultiplier, recordBytes, avgReadBytes }\n  // Return complete capacity metrics object separating average and peak rates\n  return {};\n}\n\nmodule.exports = { calculatePlatformCapacity };",
    "eSolutionCode": "function calculatePlatformCapacity(spec) {\n  const { dau, actionsPerUser, readRatio, burstMultiplier, recordBytes, avgReadBytes } = spec;\n\n  const totalDailyRequests = dau * actionsPerUser;\n  const avgTotalRps = totalDailyRequests / 86400;\n  const avgReadRps = avgTotalRps * readRatio;\n  const avgWriteRps = avgTotalRps * (1 - readRatio);\n\n  const peakTotalRps = avgTotalRps * burstMultiplier;\n  const peakReadRps = peakTotalRps * readRatio;\n  const peakWriteRps = peakTotalRps * (1 - readRatio);\n\n  const dailyRawBytes = avgWriteRps * 86400 * recordBytes;\n  const dailyRawGB = Number((dailyRawBytes / (1024 ** 3)).toFixed(2));\n\n  const peakEgressGbps = Number(((peakReadRps * avgReadBytes * 8) / 1e9).toFixed(3));\n\n  return {\n    dailyRequests: totalDailyRequests,\n    average: {\n      totalRps: Number(avgTotalRps.toFixed(1)),\n      readRps: Number(avgReadRps.toFixed(1)),\n      writeRps: Number(avgWriteRps.toFixed(1))\n    },\n    peak: {\n      totalRps: Math.round(peakTotalRps),\n      readRps: Math.round(peakReadRps),\n      writeRps: Math.round(peakWriteRps)\n    },\n    storage: {\n      dailyRawGB\n    },\n    networking: {\n      peakEgressGbps\n    }\n  };\n}\n\nmodule.exports = { calculatePlatformCapacity };",
    "eHint1": "Compute average total RPS by dividing total daily requests by 86,400. Derive average read and write rates using the provided read ratio.",
    "eHint2": "Always calculate daily storage volume using average write requests rather than instantaneous peak rates, converting bytes to gigabytes using powers of 1024.",
    "eTestCode": "const { calculatePlatformCapacity } = require('./solution');\nconst cap = calculatePlatformCapacity({\n  dau: 1000000,\n  actionsPerUser: 40,\n  readRatio: 0.9,\n  burstMultiplier: 3,\n  recordBytes: 1536,\n  avgReadBytes: 10240\n});\n\nconsole.assert(cap.average.totalRps === 463, 'Average total RPS should be 463');\nconsole.assert(cap.average.writeRps === 46.3, 'Average write RPS should be 46.3');\nconsole.assert(cap.peak.totalRps === 1389, 'Peak total RPS should be 1389');\nconsole.assert(cap.storage.dailyRawGB >= 5.5 && cap.storage.dailyRawGB <= 6.0, 'Daily raw storage should be ~5.72 GB');\nconsole.log('Day 111 Explorer Tests Passed!');",
    "aTitle": "Parameterized Cloud Infrastructure TCO Estimator",
    "aDescription": "Implement `class ParameterizedCostEstimator` taking region, instance pricing schedule, storage volume parameters, and commitment tiers; outputting comparative 12-month TCO models.",
    "aStarterCode": "class ParameterizedCostEstimator {\n  constructor(pricingSchedule) {\n    this.pricing = pricingSchedule; // { computeHourly: {}, storagePerGBMonthly: {}, egressPerGB: {} }\n  }\n\n  estimateAnnualTCO(spec) {\n    // spec: { region, instanceType, instanceCount, storageGB, monthlyEgressGB, commitmentTier }\n    // Return { monthlyCostUSD, annualCostUSD, savingsVsOnDemandUSD }\n    return {};\n  }\n}\n\nmodule.exports = { ParameterizedCostEstimator };",
    "aSolutionCode": "class ParameterizedCostEstimator {\n  constructor(pricingSchedule) {\n    this.pricing = pricingSchedule;\n  }\n\n  estimateAnnualTCO(spec) {\n    const { region, instanceType, instanceCount, storageGB, monthlyEgressGB, commitmentTier } = spec;\n\n    const computeRate = this.pricing.computeHourly[region]?.[instanceType] || 0.10;\n    const storageRate = this.pricing.storagePerGBMonthly[region] || 0.10;\n    const egressRate = this.pricing.egressPerGB[region] || 0.08;\n\n    const discountMultiplier = commitmentTier === '3YrSavings' ? 0.50 : (commitmentTier === '1YrSavings' ? 0.70 : 1.0);\n\n    const monthlyComputeBase = instanceCount * computeRate * 730;\n    const monthlyComputeDiscounted = monthlyComputeBase * discountMultiplier;\n    const monthlyStorage = storageGB * storageRate;\n    const monthlyEgress = monthlyEgressGB * egressRate;\n\n    const monthlyTotal = monthlyComputeDiscounted + monthlyStorage + monthlyEgress;\n    const annualTotal = monthlyTotal * 12;\n\n    const onDemandAnnual = (monthlyComputeBase + monthlyStorage + monthlyEgress) * 12;\n    const savingsVsOnDemand = Math.max(0, onDemandAnnual - annualTotal);\n\n    return {\n      monthlyCostUSD: Math.round(monthlyTotal),\n      annualCostUSD: Math.round(annualTotal),\n      savingsVsOnDemandUSD: Math.round(savingsVsOnDemand)\n    };\n  }\n}\n\nmodule.exports = { ParameterizedCostEstimator };",
    "aHint1": "Assume an average of seven hundred thirty operating hours per month when calculating monthly compute instance expenses from hourly pricing rates.",
    "aHint2": "Apply the commitment discount percentage solely to compute costs while calculating storage and egress fees at standard monthly rates according to the regional pricing schedule.",
    "aTestCode": "const { ParameterizedCostEstimator } = require('./solution');\nconst pricing = {\n  computeHourly: { 'us-east-1': { 'c6g.xlarge': 0.136 } },\n  storagePerGBMonthly: { 'us-east-1': 0.08 },\n  egressPerGB: { 'us-east-1': 0.09 }\n};\n\nconst estimator = new ParameterizedCostEstimator(pricing);\nconst estOnDemand = estimator.estimateAnnualTCO({\n  region: 'us-east-1',\n  instanceType: 'c6g.xlarge',\n  instanceCount: 4,\n  storageGB: 1000,\n  monthlyEgressGB: 5000,\n  commitmentTier: 'OnDemand'\n});\n\nconst estSavings = estimator.estimateAnnualTCO({\n  region: 'us-east-1',\n  instanceType: 'c6g.xlarge',\n  instanceCount: 4,\n  storageGB: 1000,\n  monthlyEgressGB: 5000,\n  commitmentTier: '1YrSavings'\n});\n\nconsole.assert(estSavings.annualCostUSD < estOnDemand.annualCostUSD, 'Savings tier should be cheaper');\nconsole.assert(estSavings.savingsVsOnDemandUSD > 1000, 'Should save over $1000 annually');\nconsole.log('Day 111 Architect Tests Passed!');"
