    "eDescription": "Implement `function calculateJitteredBackoff(attempt, baseMs, capMs, randomFn)` generating randomized backoff delays uniformly distributed between 0 and the capped exponential delay.",
    "eStarterCode": "function calculateJitteredBackoff(attempt, baseMs = 100, capMs = 5000, randomFn = Math.random) {\n  // TODO: Compute capped exponential backoff: min(capMs, baseMs * 2^attempt)\n  // TODO: Apply Full Jitter: floor(randomFn() * exponential)\n  return 0;\n}\n\nmodule.exports = { calculateJitteredBackoff };",
    "eSolutionCode": "function calculateJitteredBackoff(attempt, baseMs = 100, capMs = 5000, randomFn = Math.random) {\n  const exponential = Math.min(capMs, baseMs * (2 ** attempt));\n  const jitteredDelay = Math.floor(randomFn() * exponential);\n  return jitteredDelay;\n}\n\nmodule.exports = { calculateJitteredBackoff };",
