    "eStarterCode": "class HighScaleSystemValidator {\n  validate(spec) {\n    // spec contains { dau, actionsPerUser, readRatio, burstMultiplier, recordBytes, avgReadBytes,\n    // claimedAvgRps, claimedPeakRps, claimedDailyRawGB }\n    // Return { valid: boolean, errors: string[] }\n    return { valid: true, errors: [] };\n  }\n}\n\nmodule.exports = { HighScaleSystemValidator };",
    "eSolutionCode": "class HighScaleSystemValidator {\n  validate(spec) {\n    const errors = [];\n    const expectedDailyRequests = spec.dau * spec.actionsPerUser;\n    const expectedAvgRps = Math.round(expectedDailyRequests / 86400);\n\n    if (Math.abs(spec.claimedAvgRps - expectedAvgRps) > 2) {\n      errors.push(`Claimed average RPS ${spec.claimedAvgRps} diverges from calculated ${expectedAvgRps}`);\n    }\n\n    const expectedPeakRps = Math.round(expectedAvgRps * spec.burstMultiplier);\n    if (Math.abs(spec.claimedPeakRps - expectedPeakRps) > 5) {\n      errors.push(`Claimed peak RPS ${spec.claimedPeakRps} diverges from calculated ${expectedPeakRps}`);\n    }\n\n    const avgWriteRps = (expectedDailyRequests / 86400) * (1 - spec.readRatio);\n    const expectedDailyRawGB = (avgWriteRps * 86400 * spec.recordBytes) / (1024 ** 3);\n\n    if (Math.abs(spec.claimedDailyRawGB - expectedDailyRawGB) > 0.5) {\n      errors.push(`Claimed daily raw storage ${spec.claimedDailyRawGB} GB diverges from average write rate calculation ${expectedDailyRawGB.toFixed(2)} GB (ensure peak write rate is not erroneously used for daily accumulation)`);\n    }\n\n    return {\n      valid: errors.length === 0,\n      errors\n    };\n  }\n}\n\nmodule.exports = { HighScaleSystemValidator };",
